import{_ as a}from"./chunks/signal-graph.CpgrRyOw.js";import{_ as t,o as s,c as n,aj as o}from"./chunks/framework.C6uXqnaX.js";const m=JSON.parse('{"title":"Debug the signal graph","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/devtools/signals.md","filePath":"en/tools/devtools/signals.md"}'),i={name:"en/tools/devtools/signals.md"};function r(h,e,l,p,d,c){return s(),n("div",null,e[0]||(e[0]=[o('<h1 id="debug-the-signal-graph" tabindex="-1">Debug the signal graph <a class="header-anchor" href="#debug-the-signal-graph" aria-label="Permalink to &quot;Debug the signal graph&quot;">​</a></h1><p>The <strong>Components</strong> tab can display a live signal graph for the selected component or directive. The graph shows how the signals, computeds, effects, and other reactive nodes in that component depend on each other, which makes it easier to understand and debug reactive data flows.</p><img src="'+a+`" alt="A screenshot of the &#39;Components&#39; tab in Angular DevTools with the signal graph open for the selected component. The graph shows a signal node connected by edges to three computed nodes which the component&#39;s template reads, and the properties of the component are listed in a sidebar to the right."><h2 id="open-the-signal-graph" tabindex="-1">Open the signal graph <a class="header-anchor" href="#open-the-signal-graph" aria-label="Permalink to &quot;Open the signal graph&quot;">​</a></h2><p>In the <strong>Components</strong> tab, select a component or directive. In the property pane header, click <strong>Show Signal Graph</strong>. The signal graph opens next to the component tree.</p><p>You can also jump directly to a specific signal: in the properties view, click the signal graph button next to the property, or, when the property has more than one action, open its actions menu and choose <strong>Show in signal graph</strong>.</p><p>The <strong>Show Signal Graph</strong> button appears automatically when the inspected application supports the signal graph API — there is no setting to enable.</p><h2 id="read-the-graph" tabindex="-1">Read the graph <a class="header-anchor" href="#read-the-graph" aria-label="Permalink to &quot;Read the graph&quot;">​</a></h2><p>Nodes in the graph represent the reactive nodes that participate in the selected component:</p><ul><li><strong>Signal</strong>: a writable signal created with <code>signal()</code>.</li><li><strong>Computed</strong>: a derived value created with <code>computed()</code>.</li><li><strong>Effect</strong>: a side effect created with <code>effect()</code> or <code>afterRenderEffect()</code>.</li><li><strong>Linked signal</strong>: a writable signal created with <code>linkedSignal()</code>.</li><li><strong>Template</strong>: the component&#39;s template, which reads signals when it renders.</li><li><strong>Resource</strong>: signals that belong to a <code>resource()</code> or <code>rxResource()</code> are grouped into a collapsible cluster. Click <strong>Expand</strong> on the cluster node to see the individual nodes inside.</li></ul><p>Lines between nodes show reactive dependencies: each node is connected to the producers it reads from (upstream) and the dependants that read it (downstream).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Nodes are labeled with the <code>debugName</code> of their reactive node. Giving your signals, computeds, and especially effects — which are usually not assigned to a class member — a <code>debugName</code> makes the graph much easier to read:</p></div><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">effect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {debugName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;name in graph&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="search-the-graph" tabindex="-1">Search the graph <a class="header-anchor" href="#search-the-graph" aria-label="Permalink to &quot;Search the graph&quot;">​</a></h2><p>Click the search icon in the graph toolbar to find a node by name. Angular DevTools highlights every match and lets you step through them.</p><h2 id="inspect-a-node" tabindex="-1">Inspect a node <a class="header-anchor" href="#inspect-a-node" aria-label="Permalink to &quot;Inspect a node&quot;">​</a></h2><p>Click a node to open its details panel, which shows the node&#39;s current value as an expandable tree and offers the following actions:</p><ul><li><strong>View source</strong>: navigate to the node&#39;s definition in the Sources tab (Chrome) or Debugger tab (Firefox). The action is disabled when the source location is not available.</li><li><strong>Set breakpoint</strong>: pause execution when the signal updates. Breakpoints are only available in Chromium-based browsers.</li><li><strong>Watch signal</strong>: log the signal&#39;s updates and invalidations to the browser console. Click the action again to stop watching.</li><li><strong>Highlight upstream / downstream</strong>: trace the paths of the node&#39;s dependencies or its dependants.</li></ul><p>If the component uses no signals, Angular DevTools shows a &quot;No signals in this component&quot; message instead of the graph.</p><h2 id="version-support" tabindex="-1">Version support <a class="header-anchor" href="#version-support" aria-label="Permalink to &quot;Version support&quot;">​</a></h2><p>The signal graph requires an application built with Angular 19 or later running in development mode.</p>`,21)]))}const k=t(i,[["render",r]]);export{m as __pageData,k as default};
